function flightSimulator(canvasId) {
    // Get canvas and context
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;

    // Aircraft state
    const aircraft = {
        x: 0, y: 0, z: 0, // position (z = altitude)
        pitch: 0, roll: 0, yaw: 0, // orientation in radians
        speed: 0, // m/s
        throttle: 0, // 0 to 1
        fuel: 100, // percent
        trueSpeed: 0,
        trueAltitude: 0,
        trueHeading: 0,
        trueG: 0
    };

    // Instrument display values (may lag due to bugs)
    const instruments = {
        speed: 0,
        altitude: 0,
        heading: 0,
        fuel: 100,
        // Bug indicators
        speedLag: false,
        altitudeSticky: false,
        headingDeviation: false,
        engineFluctuation: false
    };

    // Control state
    const keys = {};

    // Constants
    const MAX_SPEED = 250; // m/s
    const MAX_THRUST = 200; // arbitrary thrust units
    const GRAVITY = 9.81; // m/s^2
    const G_FORCE_THRESHOLD = 2.5; // G's for instrument lag
    const ALTITUDE_STICKY_RANGES = [{min: 1000, max: 2000}, {min: 5000, max: 6000}];
    const MAGNETIC_ANOMALY_HEADINGS = [{center: Math.PI/2, range: Math.PI/12}]; // around 90°
    const STEEP_CLIMB_PITCH = Math.PI/6; // 30 degrees

    // Helper functions
    function toDeg(rad) { return rad * 180 / Math.PI; }
    function toRad(deg) { return deg * Math.PI / 180; }
    function clamp(val, min, max) { return Math.min(Math.max(val, min), max); }

    // Input handling
    window.addEventListener('keydown', e => { keys[e.code] = true; });
    window.addEventListener('keyup', e => { keys[e.code] = false; });

    // Main loop
    function update(dt) {
        // Throttle control (ArrowUp/ArrowDown)
        if (keys['ArrowUp']) aircraft.throttle = clamp(aircraft.throttle + dt * 0.5, 0, 1);
        if (keys['ArrowDown']) aircraft.throttle = clamp(aircraft.throttle - dt * 0.5, 0, 1);

        // Pitch control (KeyW/KeyS)
        if (keys['KeyW']) aircraft.pitch = clamp(aircraft.pitch - dt * 0.5, -Math.PI/2, Math.PI/2);
        if (keys['KeyS']) aircraft.pitch = clamp(aircraft.pitch + dt * 0.5, -Math.PI/2, Math.PI/2);

        // Roll control (KeyA/KeyD)
        if (keys['KeyA']) aircraft.roll = clamp(aircraft.roll - dt * 0.5, -Math.PI/2, Math.PI/2);
        if (keys['KeyD']) aircraft.roll = clamp(aircraft.roll + dt * 0.5, -Math.PI/2, Math.PI/2);

        // Yaw control (KeyQ/KeyE)
        if (keys['KeyQ']) aircraft.yaw -= dt * 0.5;
        if (keys['KeyE']) aircraft.yaw += dt * 0.5;

        // Engine thrust (intentional bug: fluctuation during steep climbs)
        let thrust = aircraft.throttle * MAX_THRUST;
        if (Math.abs(aircraft.pitch) > STEEP_CLIMB_PITCH) {
            // Intentional engine power fluctuation bug
            const fluct = Math.sin(Date.now() / 200) * 0.2; // +/-20% fluctuation
            thrust *= 1 + fluct;
            instruments.engineFluctuation = true;
        } else {
            instruments.engineFluctuation = false;
        }

        // Acceleration along forward vector
        const forwardX = Math.cos(aircraft.yaw) * Math.cos(aircraft.pitch);
        const forwardY = Math.sin(aircraft.yaw) * Math.cos(aircraft.pitch);
        const forwardZ = Math.sin(aircraft.pitch);
        const accel = thrust / 1000; // simple conversion to m/s^2

        // Update speed and vertical speed
        const prevVZ = aircraft.trueSpeed * forwardZ;
        aircraft.trueSpeed = clamp(aircraft.trueSpeed + accel * dt, 0, MAX_SPEED);
        const newVZ = aircraft.trueSpeed * forwardZ;
        const deltaVZ = newVZ - prevVZ;
        // Compute G-force (vertical acceleration)
        aircraft.trueG = Math.abs(deltaVZ / dt) / GRAVITY;

        // Update position
        aircraft.x += forwardX * aircraft.trueSpeed * dt;
        aircraft.y += forwardY * aircraft.trueSpeed * dt;
        aircraft.z += forwardZ * aircraft.trueSpeed * dt;
        aircraft.z = Math.max(aircraft.z, 0); // ground level

        // Update true altitude and heading
        aircraft.trueAltitude = aircraft.z;
        aircraft.trueHeading = (toDeg(aircraft.yaw) + 360) % 360;

        // Fuel consumption
        aircraft.fuel = clamp(aircraft.fuel - aircraft.throttle * dt * 0.5, 0, 100);

        // Instrument updates with intentional bugs

        // Speed lag during high G-forces (bug)
        if (aircraft.trueG > G_FORCE_THRESHOLD) {
            instruments.speedLag = true;
            // Apply lag: interpolate slowly
            instruments.speed += (aircraft.trueSpeed - instruments.speed) * dt * 0.5;
        } else {
            instruments.speedLag = false;
            instruments.speed = aircraft.trueSpeed;
        }

        // Altimeter stickiness at certain altitudes (bug)
        const sticky = ALTITUDE_STICKY_RANGES.some(range => aircraft.trueAltitude >= range.min && aircraft.trueAltitude <= range.max);
        if (sticky) {
            instruments.altitudeSticky = true;
            // Stickiness: only update when altitude changes > 10m
            if (Math.abs(aircraft.trueAltitude - instruments.altitude) > 10) {
                instruments.altitude = aircraft.trueAltitude;
            }
        } else {
            instruments.altitudeSticky = false;
            instruments.altitude = aircraft.trueAltitude;
        }

        // Compass deviation near magnetic anomalies (bug)
        const anomaly = MAGNETIC_ANOMALY_HEADINGS.some(a => {
            const diff = Math.abs((aircraft.yaw - a.center + Math.PI) % (2*Math.PI) - Math.PI);
            return diff < a.range;
        });
        if (anomaly) {
            instruments.headingDeviation = true;
            // Add deviation up to +/-5 degrees
            const dev = (Math.random() - 0.5) * 10;
            instruments.heading = (aircraft.trueHeading + dev + 360) % 360;
        } else {
            instruments.headingDeviation = false;
            instruments.heading = aircraft.trueHeading;
        }

        // Fuel display (no bug)
        instruments.fuel = aircraft.fuel;
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Simple 3D perspective: draw horizon line based on pitch
        const horizonY = canvas.height / 2 - Math.tan(aircraft.pitch) * 200;
        ctx.strokeStyle = '#777';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, horizonY);
        ctx.lineTo(canvas.width, horizonY);
        ctx.stroke();

        // Simple terrain: draw a few lines receding into distance
        ctx.strokeStyle = '#555';
        for (let i = 1; i <= 5; i++) {
            const offset = i * 30;
            const lineY = horizonY + offset * Math.cos(aircraft.roll);
            ctx.beginPath();
            ctx.moveTo(0, lineY);
            ctx.lineTo(canvas.width, lineY);
            ctx.stroke();
        }

        // HUD background
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(0, 0, canvas.width, 60);

        // HUD text
        ctx.fillStyle = '#0f0';
        ctx.font = '14px monospace';
        const pad = (n, w) => n.toString().padStart(w, '0');
        const speedText = `SPD:${pad(Math.round(instruments.speed),3)}m/s`;
        const altText = `ALT:${pad(Math.round(instruments.altitude),5)}m`;
        const hdgText = `HDG:${pad(Math.round(instruments.heading),3)}°`;
        const fuelText = `FUEL:${pad(Math.round(instruments.fuel),3)}%`;
        ctx.fillText(speedText, 10, 20);
        ctx.fillText(altText, 150, 20);
        ctx.fillText(hdgText, 300, 20);
        ctx.fillText(fuelText, 440, 20);

        // Visual bug indicators (red exclamation marks)
        const indicatorSize = 8;
        if (instruments.speedLag) {
            ctx.fillStyle = 'red';
            ctx.fillText('!', 70, 20);
        }
        if (instruments.altitudeSticky) {
            ctx.fillStyle = 'red';
            ctx.fillText('!', 230, 20);
        }
        if (instruments.headingDeviation) {
            ctx.fillStyle = 'red';
            ctx.fillText('!', 380, 20);
        }
        if (instruments.engineFluctuation) {
            ctx.fillStyle = 'red';
            ctx.fillText('!', 520, 20);
        }
    }

    let lastTime = null;
    function loop(timestamp) {
        if (!lastTime) lastTime = timestamp;
        const dt = (timestamp - lastTime) / 1000; // seconds
        lastTime = timestamp;

        update(dt);
        draw();

        requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
}
